drop table if exists enterprise_economic_info;
create table enterprise_economic_info
(
    id             char(20)              not null comment '统一信用代码' primary key,
    deleted        boolean default false not null comment '逻辑删除',
    create_time    datetime              not null comment '创建时间',
    update_time    datetime              not null comment '修改时间',
    year_2023      float                 null comment '2023年产值',
    year_2024      float                 null comment '2024年产值',
    year_2025      float as (ifnull(quarter_2025_1, 0) +
                             ifnull(quarter_2025_2, 0) +
                             ifnull(quarter_2025_3, 0) +
                             ifnull(quarter_2025_4, 0)) comment '2025年产值',
    quarter_2025_1 float                 null comment '2025年一季度产值',
    quarter_2025_2 float                 null comment '2025年二季度产值',
    quarter_2025_3 float                 null comment '2025年三季度产值',
    quarter_2025_4 float                 null comment '2025年四季度产值'
) comment '企业经济数据';

insert into enterprise_economic_info (id, deleted, create_time, update_time, year_2023, year_2024,
                                      quarter_2025_1, quarter_2025_2, quarter_2025_3,
                                      quarter_2025_4)
