drop table if exists enterprise_tag_info;
create table enterprise_tag_info
(
    id                                      char(20)              not null comment '统一信用代码' primary key,
    deleted                                 boolean default false not null comment '逻辑删除',
    create_time                             datetime              not null comment '创建时间',
    update_time                             datetime              not null comment '修改时间',
    listing_situation                       varchar(32)           null comment '上市情况',
    national_green_factory                  varchar(4)            null comment '国家级绿色工厂',
    provincial_green_factory                varchar(4)            null comment '省级绿色工厂',
    national_zjtx                           varchar(4)            null comment '国家级专精特新',
    provincial_zjtx                         varchar(4)            null comment '省级级专精特新',
    municipal_zjtx                          varchar(4)            null comment '市级专精特新',
    provincial_industrial_internet_platform varchar(4)            null comment '省工业互联网平台',
    provincial_benchmark_factory            varchar(4)            null comment '省标杆工厂',
    provincial_intelligent_workshop         varchar(4)            null comment '省智能车间',
    provincial_intelligent_factory          varchar(4)            null comment '省智能工厂',
    strengthening_peaks_enhancing_chains    varchar(4)            null comment '筑峰强链',
    high_tech                               varchar(4)            null comment '高企',
    gazelle                                 varchar(4)            null comment '瞪羚企业',
    unicorn                                 varchar(4)            null comment '独角兽企业'
) comment '企业标签数据';

insert into enterprise_tag_info (id, deleted, create_time, update_time, listing_situation,
                                 national_green_factory, provincial_green_factory, national_zjtx,
                                 provincial_zjtx, municipal_zjtx,
                                 provincial_industrial_internet_platform,
                                 provincial_benchmark_factory, provincial_intelligent_workshop,
                                 provincial_intelligent_factory,
                                 strengthening_peaks_enhancing_chains, high_tech, gazelle, unicorn)
